<script lang="ts">
  import { invalidateAll } from '$app/navigation';
  let { data } = $props();
  let page = $state('gtd');
  let gtdView = $state<'actions'|'projects'>('actions');
  let selected: any = $state(null);
  let previousProject: any = $state(null);
  let query = $state('');
  let filter = $state('all');
  let selectedFacets = $state<string[]>([]);
  let maxMinutes = $state(240);
  let energyPosition = $state(0);
  let facetTab = $state<'contexts'|'people'|'tags'>('contexts');
  let projectQuery = $state('');
  let projectStatus = $state<string[]>([]);
  let projectImportance = $state('all');
  let maxAltitude = $state(50000);
  let referenceQuery = $state('');
  let cart: any[] = $state([]);
  let activeProject: any = $state(null);
  let captureOpen = $state(false);
  let captureText = $state('');
  let saveState = $state('');
  let flashPath = $state('');
  let edit: any = $state({});

  const cockpit = $derived(data.gtdCockpit);
  const allProjects = $derived(cockpit.projects);
  const noNextProjects = $derived(cockpit.projects.filter((p:any) => p.noNextAction));
  const facetValues = $derived({
    contexts: [...new Set(cockpit.contextOptions.map((v:string)=>v.replace(/^@/,'')))],
    people: cockpit.peopleOptions,
    tags: cockpit.tagOptions
  });
  const projectStatuses = $derived([...new Set(allProjects.map((p:any)=>p.status).filter(Boolean))]);
  const filteredActions = $derived(cockpit.next.filter((a:any) => matches(a, filter, query) && selectedFacets.every((facet)=>matches(a, facet, '')) && matchesDuration(a,maxMinutes) && matchesEnergy(a,energyPosition)));
  const filteredProjects = $derived(allProjects.filter((p:any) => projectMatches(p, projectQuery)));
  const projectActions = $derived(activeProject ? cockpit.next.filter((a:any) => a.projectId === activeProject.id || a.project === activeProject.title) : []);
  const filteredReferences = $derived(cockpit.references.filter((r:any) => referenceMatches(r, referenceQuery)).slice(0,80));
  const refsForSelection = $derived(selected ? cockpit.references.filter((r:any) => r.projectId === selected.id || r.projectId === selected.projectId || r.actionId === selected.id).slice(0,12) : []);

  function hay(item:any){ return [item.title,item.status,item.priority,item.project,item.projectId,item.finish,item.criterion,item.guardrail,item.result,item.excerpt,item.altitude,item.importance,item.dueAt,...(item.contexts||[]),...(item.tags||[]),...(item.people||[])].filter(Boolean).join(' ').toLowerCase(); }
  function hasUrgent(item:any){ return /(urgent|critique|important|p1|deadline|bloquant|rouge)/i.test(hay(item)); }
  function inCart(item:any){ return cart.some((x:any)=>x.path===item.path); }
  function matches(item:any, f:string, q:string){ const text=hay(item); const qq=q.trim().toLowerCase(); if(qq && !text.includes(qq)) return false; if(f==='all') return true; if(f==='5-15min') return /5\s*[–-]\s*15|15\s*min|rapide|court|quart/.test(text); if(f==='30min+') return /30\s*min|45\s*min|1\s*h|long|profond|focus/.test(text); if(f==='énergie basse') return /énergie basse|energie basse|facile|léger|leger|fatigue/.test(text); if(f==='énergie haute') return /énergie haute|energie haute|complexe|profond|focus|concentration/.test(text); if(f==='sensible') return /finance|santé|sante|juridique|électricité|electricite|achat|publication|sensible/.test(text); if(f==='blocked') return /blocked|bloqué|bloque|waiting|attente/.test(text); if(f==='important'||f==='urgent') return hasUrgent(item); if(f.startsWith('avec:')) return (item.people||[]).map((p:string)=>p.toLowerCase()).includes(f.slice(5).toLowerCase()) || text.includes(f.slice(5).toLowerCase()); return text.includes(f.replace(/^@/,'').toLowerCase()); }
  function durationOf(item:any){ const text=hay(item); const m=text.match(/(\d+)\s*(?:min|minutes?)/); return m?Number(m[1]):0; }
  function matchesDuration(item:any,max:number){ const minutes=durationOf(item); return !minutes || minutes<=max; }
  function matchesEnergy(item:any,position:number){ if(position===0) return true; const level=['','low','medium','high'][position]; const text=hay(item); if(level==='low') return /énergie basse|energie basse|facile|léger|leger|fatigue/.test(text); if(level==='high') return /énergie haute|energie haute|complexe|profond|focus|concentration/.test(text); return !/énergie basse|energie basse|énergie haute|energie haute/.test(text); }
  function toggleFacet(value:string){ selectedFacets=selectedFacets.includes(value)?selectedFacets.filter(v=>v!==value):[...selectedFacets,value]; }
  function toggleCart(item:any){ if(inCart(item)) removeCart(item); else addCart(item); }
  function isFaded(project:any){ return /parking|someday|maybe|parked/.test((project.status||'').toLowerCase()); }
  function projectMatches(project:any, q:string){ const text=hay(project); const qq=q.trim().toLowerCase(); if(qq && !text.includes(qq)) return false; if(projectStatus.length && !projectStatus.includes(project.status)) return false; if(Number(project.altitude||0)>maxAltitude) return false; if(projectImportance!=='all' && (project.importance||'none').toLowerCase()!==projectImportance) return false; return true; }
  function referenceMatches(ref:any, q:string){ const qq=q.trim().toLowerCase(); if(!qq) return true; return [ref.title,ref.excerpt,ref.projectId,ref.actionId,...(ref.tags||[])].filter(Boolean).join(' ').toLowerCase().includes(qq); }
  async function openDetail(item:any, kind='action', fromProject=false){ if(fromProject && activeProject) previousProject=activeProject; selected={...item,kind}; edit={ title:item.title||'', status:item.status||'', priority:item.priority||'', projectId:item.projectId||'', project:item.project||'', contexts:(item.contexts||[]).join(', '), tags:(item.tags||[]).join(', '), people:(item.people||[]).join(', '), dueAt:item.dueAt||'', scheduledAt:item.scheduledAt||'', followupAt:item.followupAt||'', postponedUntil:item.postponedUntil||'', finish:item.finish||item.criterion||'', altitude:item.altitude||'', importance:item.importance||'', result:item.result||'', markdown:'chargement…' }; try { const res=await fetch(`/api/gtd/item?path=${encodeURIComponent(item.path)}`); if(res.ok){ const raw=await res.json(); if(selected?.path===item.path) edit.markdown=raw.markdown||''; } else edit.markdown=item.excerpt||''; } catch { edit.markdown=item.excerpt||''; } }
  function closeDetail(){ selected=null; previousProject=null; saveState=''; }
  function openProject(project:any){ activeProject=project; previousProject=null; openDetail(project,'project'); }
  function backToProject(){ if(previousProject) openProject(previousProject); }
  function addCart(item:any){ if(inCart(item)) return; cart=[...cart,item]; flashPath=item.path; setTimeout(()=>{ if(flashPath===item.path) flashPath=''; }, 700); }
  function removeCart(item:any){ cart=cart.filter((x:any)=>x.path!==item.path); }
  function refHref(r:any){ return `${data.links.gtdwiki.replace(/\/$/,'')}/files/public/GTD/${r.path}`; }
  async function saveSelected(extra:Record<string,unknown>={}){
    if(!selected) return;
    saveState='sauvegarde…';
    const fields={ title:edit.title, status:edit.status, priority:edit.priority, projectId:edit.projectId, project:edit.project, contexts:edit.contexts, tags:edit.tags, people:edit.people, dueAt:edit.dueAt, scheduledAt:edit.scheduledAt, followupAt:edit.followupAt, postponedUntil:edit.postponedUntil, finish:edit.finish, altitude:edit.altitude, importance:edit.importance, result:edit.result, ...extra };
    const res=await fetch('/api/gtd/item',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({path:selected.path,kind:selected.kind,fields,markdown:edit.markdown})});
    if(!res.ok){ saveState=`erreur ${res.status}`; return; }
    saveState='sauvé'; await invalidateAll(); setTimeout(()=>saveState='',1200);
  }
  async function quickCapture(){ const text=captureText.trim(); if(!text) return; saveState='capture…'; const res=await fetch('/api/gtd/item',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({create:true,kind:'inbox',fields:{title:text,status:'inbox'},markdown:text})}); if(res.ok){ captureText=''; captureOpen=false; await invalidateAll(); saveState='capturé'; setTimeout(()=>saveState='',1200); } else saveState=`capture erreur ${res.status}`; }
</script>

<svelte:head><title>hAIrem GTD cockpit</title></svelte:head>
<main class="shell">
  <section class="topbar panel">
    <div class="brand"><span class="heart"></span><b>hAIrem</b><small>GTD</small></div>
    <div class="leds">{#each data.runtime.components as c}<svelte:element this={c.href?'a':'span'} class="led" href={c.href} target={c.href?'_blank':undefined} rel="noreferrer" aria-label={c.aria || c.detail || c.label}><i class:ok={c.led==='ok'} class:warn={c.led==='warn'} class:down={c.led==='down'}></i>{c.label}<span class="tip"><b>{c.label}</b>{#if c.primaryIssue}<code class="issue">{c.primaryIssue}</code>{/if}{#if c.tableRows?.length}<table><thead><tr><th>bank</th><th>facts</th><th>pend</th><th>run</th><th>stuck</th><th>fail</th><th>llm</th><th>last</th></tr></thead><tbody>{#each c.tableRows as r}<tr class:bad={r.stuck||r.failed||r.llm1h}><td>{r.bank}</td><td>{r.facts}</td><td>{r.pending}</td><td>{r.running}</td><td>{r.stuck}</td><td>{r.failed}</td><td>{r.llm1h}/{r.llm24h}</td><td>{r.last}</td></tr>{/each}</tbody></table>{:else}{#each c.detailLines as l}<code>{l}</code>{/each}{/if}</span></svelte:element>{/each}</div>
    <nav><button class="capture-button" onclick={()=>captureOpen=true}>capture rapide</button><code class="version" aria-label="Version du dashboard">v{data.version}</code></nav>
  </section>
  <section class="authority"><b>Katia GTD</b><span>Dashboard = vue + édition Markdown contrôlée.</span><code>{cockpit.schema}{saveState ? ` · ${saveState}` : ''}</code></section>
  <section class="tabs panel">{#each [['status','Status',data.runtime.components.filter((c:any)=>c.led!=='ok').length],['gtd','GTD',cockpit.next.length + allProjects.length],['productivity','Productivité',cart.length],['references','Références',cockpit.references.length],['review','Review',cockpit.review.length + noNextProjects.length + cockpit.inbox.length]] as t}<button class:active={page===t[0]} onclick={()=>page=t[0]}>{t[1]} <b>{t[2]}</b></button>{/each}</section>
  {#if page==='status'}<section class="panel page"><header><p>Système</p><h1>Status</h1><span>État live des composants du domaine.</span></header><div class="cards compact">{#each data.runtime.components as component}<article class="card"><strong><i class:ok={component.led==='ok'} class:warn={component.led==='warn'} class:down={component.led==='down'}></i> {component.label}</strong>{#each component.detailLines.slice(0,5) as line}<code>{line}</code>{/each}</article>{/each}</div></section>{/if}
  {#if page==='gtd'}<section class="tabs gtd-tabs"><button class:active={gtdView==='actions'} onclick={()=>gtdView='actions'}>Actions <b>{cockpit.next.length}</b></button><button class:active={gtdView==='projects'} onclick={()=>gtdView='projects'}>Projets <b>{allProjects.length}</b></button></section>{/if}

  {#if page==='gtd' && gtdView==='actions'}
    <section class="work actions-view"><aside class="panel side"><h2>Filtres</h2><input bind:value={query} placeholder="chercher…" /><div class="facet-tabs">{#each [['contexts','Contextes'],['people','Personnes'],['tags','Tags']] as tab}<button class:active={facetTab===tab[0]} onclick={()=>facetTab=tab[0] as typeof facetTab}>{tab[1]}</button>{/each}</div><div class="chipgrid">{#each facetValues[facetTab] as facet}<button class:active={selectedFacets.includes(facet)} onclick={()=>toggleFacet(facet)}>{facet}</button>{/each}</div><label>Temps max : {maxMinutes >= 240 ? 'sans limite' : `${maxMinutes} min`}<input type="range" min="0" max="240" step="5" bind:value={maxMinutes}/></label><label>Énergie : {['toutes','bas','moyen','haut'][energyPosition]}<input type="range" min="0" max="3" step="1" bind:value={energyPosition}/><small>0 = aucun filtre · 1 bas · 2 moyen · 3 haut</small></label></aside><article class="panel main"><header><p>Choisir maintenant</p><h1>Actions</h1><span>{filteredActions.length}/{cockpit.next.length} visibles · panier {cart.length}</span></header><div class="cards">{#each filteredActions as a}<article class:urgent={hasUrgent(a)} class:in-cart={inCart(a)} class="card action"><button class="cardopen" onclick={()=>toggleCart(a)} aria-label={`Ajouter ou retirer ${a.title} du panier`}><div class="row"><strong>{a.title}</strong>{#if hasUrgent(a)}<small class="redflag">important</small>{/if}</div><div class="chips meta">{#each [a.priority,...(a.people||[]).map((p:string)=>`avec ${p}`)].filter(Boolean).slice(0,4) as m}<em>{m}</em>{/each}</div></button><footer><span>{inCart(a)?'✓ dans le panier':a.updatedAt||'n/a'}</span><button type="button" onclick={()=>openDetail(a,'action')}>éditer</button></footer></article>{/each}</div></article></section>
  {/if}

  {#if page==='gtd' && gtdView==='projects'}
    <section class="work"><aside class="panel side"><h2>Filtres projets</h2><input bind:value={projectQuery} placeholder="chercher projet…" /><fieldset><legend>Statut</legend>{#each projectStatuses as status}<label><input type="checkbox" checked={projectStatus.includes(status)} onchange={()=>projectStatus=projectStatus.includes(status)?projectStatus.filter(s=>s!==status):[...projectStatus,status]}/>{status}</label>{/each}</fieldset><label>Altitude max : {maxAltitude===50000?'toutes':maxAltitude}<input type="range" min="0" max="50000" step="1000" bind:value={maxAltitude}/></label><label>Importance<select bind:value={projectImportance}><option value="all">toutes</option><option value="none">none</option><option value="low">low</option><option value="med">med</option><option value="high">high</option></select></label></aside><article class="panel main"><header><p>Vision projets</p><h1>Projets</h1><span>{filteredProjects.length}/{allProjects.length} projets</span></header><div class="cards projects">{#each filteredProjects as p}<button class="card project" class:warncard={p.noNextAction} class:faded={isFaded(p)} class:urgent={hasUrgent(p)} onclick={()=>openProject(p)}>{#if p.noNextAction}<span class="warning" title="Projet actif sans next action">⚠</span>{/if}<strong>{p.title}</strong><div class="chips">{#each [p.status,p.altitude,...(p.tags||[])].filter(Boolean).slice(0,8) as tag}<em>{tag}</em>{/each}</div><code>Next: {p.nextAction||'aucune next action liée'}</code><footer>{#if p.dueAt}<span>{p.dueAt}</span>{/if}<span>{p.linkedActions} actions · {p.references} refs</span></footer></button>{/each}</div></article></section>
  {/if}

  {#if page==='productivity'}
    <section class="panel page"><header><p>Activation</p><h1>Productivité</h1><span>Panier de travail choisi consciemment.</span></header><h2>Panier</h2>{#if cart.length}<div class="cards compact">{#each cart as a}<article class="card action"><button class="cardopen" onclick={()=>openDetail(a,'action')}><strong>{a.title}</strong></button><footer><span>{(a.contexts||[]).join(', ')}</span><button onclick={()=>removeCart(a)}>retirer</button></footer></article>{/each}</div>{:else}<div class="empty">Panier vide. Clique une carte dans Actions pour l’ajouter.</div>{/if}</section>
  {/if}

  {#if page==='references'}
    <section class="panel page"><header><p>Base de consultation</p><h1>Références</h1><span>Documents, personnes et autres notes liées au GTD.</span></header><input bind:value={referenceQuery} placeholder="chercher référence, projet, personne…"/><div class="cards compact">{#each filteredReferences as r}<button class="card" onclick={()=>openDetail(r,'reference')}><strong>{r.title}</strong><p>{r.excerpt}</p><small>{r.projectId||r.actionId||'global'}</small></button>{/each}</div></section>
  {/if}

  {#if page==='review'}
    <section class="panel page"><header><p>Pré-revue Katia</p><h1>Review</h1><span>Anomalies, inbox et waiting éditables.</span></header><div class="alerts">{#each cockpit.review as r}<article>⚠️ {r}</article>{/each}</div><h2>Inbox</h2><div class="cards compact">{#each cockpit.inbox.slice(0,24) as a}<button class="card" onclick={()=>openDetail(a,'inbox')}><strong>{a.title}</strong><p>{a.excerpt}</p></button>{/each}</div><h2>Projets actifs sans next action</h2><div class="cards projects">{#each noNextProjects as p}<button class="card warncard" onclick={()=>openProject(p)}><strong>{p.title}</strong><p>{p.result||p.excerpt}</p></button>{/each}</div><h2>Waiting / blocked</h2><div class="cards compact">{#each cockpit.waiting.slice(0,24) as a}<button class="card" onclick={()=>openDetail(a,'waiting')}><strong>{a.title}</strong><p>{a.finish||a.excerpt}</p><small>{a.followupAt||a.scheduledAt||'sans date'}</small></button>{/each}</div></section>
  {/if}
</main>

{#if captureOpen}<div class="modal-backdrop" role="presentation" onclick={()=>captureOpen=false}><div class="modal panel capture-modal" role="dialog" aria-modal="true" tabindex="-1" onclick={(e)=>e.stopPropagation()} onkeydown={(event)=>{ if(event.key==='Escape') captureOpen=false; }}><header class="modal-head"><div><p>inbox</p><h1>Capture rapide</h1></div><button class="close" onclick={()=>captureOpen=false}>×</button></header><textarea bind:value={captureText} placeholder="Déposer dans l’inbox GTD…"></textarea><div class="proposal"><button class="primary" onclick={quickCapture}>capturer</button><small>Crée un .md status=inbox dans actions/.</small></div></div></div>{/if}

{#if selected}<div class="modal-backdrop" role="presentation" onclick={closeDetail}><div class="modal panel" role="dialog" aria-modal="true" aria-labelledby="detail-title" tabindex="-1" onclick={(event)=>event.stopPropagation()} onkeydown={(event)=>{ if(event.key==='Escape') closeDetail(); }}><header class="modal-head"><div><p>{selected.kind||'item'} · {selected.path}</p><h1 id="detail-title">{selected.title}</h1></div><button class="close" onclick={closeDetail} aria-label="Fermer">×</button></header><div class="modal-grid"><article class="editform"><label>Titre<input bind:value={edit.title}/></label><label>Statut<select bind:value={edit.status}>{#each ['inbox','ready','next','waiting_for','blocked','scheduled','someday','done'] as status}<option value={status}>{status}</option>{/each}</select></label>{#if selected.kind==='project'}<label>Altitude<input type="number" min="0" max="50000" bind:value={edit.altitude}/></label><label>Importance<select bind:value={edit.importance}><option value="none">none</option><option value="low">low</option><option value="med">med</option><option value="high">high</option></select></label>{:else}<label>Priorité<select bind:value={edit.priority} disabled={Boolean(edit.dueAt)}><option value="">—</option>{#each ['P1','P2','P3','P4'] as p}<option value={p}>{p}</option>{/each}</select></label><label>Projet<select bind:value={edit.projectId}><option value="">none</option>{#each allProjects as project}<option value={project.id}>{project.title}</option>{/each}</select></label>{/if}<label>Deadline<input type="date" bind:value={edit.dueAt}/></label><label>Contextes<input bind:value={edit.contexts}/></label><label>Tags<input bind:value={edit.tags}/></label><label>Personnes<input bind:value={edit.people}/></label><label>Fini quand<input bind:value={edit.finish}/></label><label>Résumé / corps court<textarea bind:value={edit.markdown}></textarea></label><div class="proposal"><button class="primary" onclick={()=>saveSelected()}>sauver</button>{#if selected.kind!=='project'}<button onclick={()=>saveSelected({status:'done'})}>done</button><button onclick={()=>saveSelected({status:'waiting'})}>waiting</button><button onclick={()=>saveSelected({status:'blocked'})}>blocked</button><button onclick={()=>saveSelected({status:'someday'})}>parquer</button>{/if}<small>{saveState||'Écrit directement le Markdown avec audit local.'}</small></div></article><aside>{#if previousProject}<button class="mini back" onclick={backToProject}>← retour projet</button>{/if}{#if selected.kind==='project'}<h2>Actions liées</h2>{#each projectActions as a}<button class="mini" onclick={()=>openDetail(a,'action',true)}>{a.title}</button>{/each}{/if}<h2>Références liées</h2>{#if refsForSelection.length}{#each refsForSelection as r}<a class="ref" href={refHref(r)} target="_blank" rel="noreferrer">{r.title}</a>{/each}{:else}<p class="muted">Aucune référence liée détectée.</p>{/if}</aside></div></div></div>{/if}

<style>
:global(body){margin:0;background:#05070b;color:#dff8ff;font-family:Inter,ui-sans-serif,system-ui,sans-serif}.shell{max-width:1540px;margin:0 auto;padding:12px}.panel{background:rgba(8,15,25,.86);border:1px solid rgba(100,220,255,.16);border-radius:14px;box-shadow:0 14px 44px rgba(0,0,0,.30)}a{color:#68e7ff;text-decoration:none}button{font:inherit}.topbar{position:sticky;top:0;z-index:20;display:flex;gap:12px;align-items:center;padding:7px 10px;backdrop-filter:blur(10px)}.brand{display:flex;align-items:center;gap:8px;min-width:128px}.brand small{color:#8aa6b8}.heart{width:16px;height:16px;border-radius:50%;background:radial-gradient(circle,#ff2c68 0 35%,#163245 40%);box-shadow:0 0 14px #ff2c68}.leds{display:flex;gap:6px;flex-wrap:wrap;flex:1}.led{position:relative;display:inline-flex;align-items:center;gap:5px;padding:3px 7px;border:1px solid rgba(104,231,255,.16);border-radius:999px;background:rgba(255,255,255,.03);font-size:11px;line-height:1.2}.tip{display:none;position:absolute;top:calc(100% + 8px);left:0;min-width:360px;max-width:900px;padding:12px;border-radius:12px;border:1px solid rgba(104,231,255,.3);background:#06101b;z-index:40}.led:hover .tip{display:grid;gap:4px}.tip table{border-collapse:collapse;font:11px ui-monospace,monospace}.tip td,.tip th{padding:3px 6px;border-bottom:1px solid rgba(104,231,255,.12)}.bad td,.issue{color:#ffd447}i{display:inline-block;width:8px;height:8px;border-radius:50%;background:#607080}.ok{background:#28ff9c;box-shadow:0 0 9px #28ff9c}.warn{background:#ffd447;box-shadow:0 0 9px #ffd447}.down{background:#ff3f6e;box-shadow:0 0 9px #ff3f6e}nav{display:flex;gap:10px;font-size:12px;align-items:center}.capture-button,.tabs button,.side button,.card footer button,.proposal button{border:1px solid rgba(104,231,255,.16);border-radius:999px;background:rgba(255,255,255,.03);color:#dff8ff;padding:8px 12px;cursor:pointer}.capture-button,.proposal .primary{background:#68e7ff;color:#06101b;border:0}.authority{max-width:1540px;margin:10px auto 0;padding:0 4px;display:flex;gap:10px;align-items:center;color:#8aa6b8;font-size:12px}.authority b{color:#ffd447}.authority code{margin-left:auto}.tabs{margin-top:10px;padding:7px;display:flex;gap:8px;flex-wrap:wrap}.tabs button.active,.side button.active{background:rgba(104,231,255,.16);border-color:rgba(104,231,255,.45)}.work{display:grid;grid-template-columns:260px minmax(0,1fr);gap:12px;margin-top:12px}.side,.main,.page{padding:14px}.side{display:grid;align-content:start;gap:9px}.side h2{margin:0 0 8px}.side details{border:1px solid rgba(104,231,255,.1);border-radius:12px;padding:8px}.side summary{cursor:pointer;color:#68e7ff;font-size:12px;text-transform:uppercase;letter-spacing:.12em}.chipgrid{display:flex;flex-wrap:wrap;gap:6px;margin-top:8px}.chipgrid button{padding:5px 8px;font-size:12px}input,textarea{width:100%;box-sizing:border-box;border:1px solid rgba(104,231,255,.18);background:rgba(255,255,255,.04);color:#dff8ff;border-radius:10px;padding:10px}textarea{min-height:120px}header{margin-bottom:14px}header p{margin:0 0 5px;color:#68e7ff;text-transform:uppercase;letter-spacing:.18em;font-size:11px}h1{margin:0 0 4px;font-size:30px}h2{margin:14px 0 10px}.cards{display:grid;grid-template-columns:repeat(auto-fit,minmax(315px,1fr));gap:10px}.cards.projects{grid-template-columns:repeat(auto-fit,minmax(360px,1fr))}.cards.compact{grid-template-columns:repeat(auto-fit,minmax(280px,1fr))}.card{border:1px solid rgba(104,231,255,.12);border-radius:13px;background:rgba(255,255,255,.03);color:#dff8ff;padding:12px;text-align:left;font:inherit;transition:transform .18s,border-color .18s,box-shadow .18s}.card:hover{border-color:rgba(104,231,255,.38)}.card.flash{animation:pop .55s ease}.urgent{border-color:rgba(255,63,110,.75);box-shadow:0 0 0 1px rgba(255,63,110,.18)}.redflag{color:#ff637f;background:transparent;border:1px solid #ff3f6e;border-radius:999px;padding:2px 7px}button.card{cursor:pointer}.cardopen{display:block;width:100%;padding:0;border:0;background:transparent;color:inherit;text-align:left;font:inherit;cursor:pointer}.card strong{display:block;color:#fff}.card p,.modal p{color:#adc6d4;line-height:1.45}.row{display:flex;justify-content:space-between;gap:10px}.chips{display:flex;gap:5px;flex-wrap:wrap;margin:8px 0}.chips em{font-style:normal;color:#b9f4ff;border:1px solid rgba(104,231,255,.16);background:rgba(104,231,255,.06);border-radius:999px;padding:3px 7px;font-size:11px}.chips.meta em{color:#ffd447;border-color:rgba(255,212,71,.2);background:rgba(255,212,71,.06)}.references-inline{margin-top:16px}.card footer{display:flex;justify-content:space-between;gap:10px;align-items:center;margin-top:10px;color:#8aa6b8;font-size:12px}.footactions{display:flex;gap:6px}.card footer button{padding:5px 8px}.card footer .addcart{border:0;color:#071016;background:#68e7ff}.card footer .addcart:disabled{background:#28414a;color:#8aa6b8;cursor:default}.warncard{border-color:rgba(255,212,71,.45);background:rgba(255,212,71,.055)}.warning{color:#ffd447;float:right;font-size:18px}.faded{opacity:.42;filter:saturate(.55);transition:opacity .18s,filter .18s}.faded:hover{opacity:1;filter:none}.in-cart{background:rgba(104,231,255,.13);border-color:#68e7ff;box-shadow:0 0 14px rgba(104,231,255,.16)}.facet-tabs{display:flex;gap:4px}.facet-tabs button{flex:1;padding:6px}.side fieldset{border:1px solid rgba(104,231,255,.12);border-radius:10px;display:flex;flex-wrap:wrap;gap:5px}.side fieldset label{display:flex;gap:5px;align-items:center;font-size:12px}.side select,.editform select{width:100%;box-sizing:border-box;border:1px solid rgba(104,231,255,.18);background:#0b1521;color:#dff8ff;border-radius:10px;padding:10px}.side label{display:grid;gap:6px;font-size:12px;color:#8aa6b8}.side input[type=range]{padding:0}code{display:block;font:12px ui-monospace,monospace;color:#b9f4ff;margin:3px 0;overflow-wrap:anywhere}.page{margin-top:12px}.empty,.alerts article{padding:14px;border:1px dashed rgba(104,231,255,.2);border-radius:12px;color:#8aa6b8}.alerts{display:grid;gap:8px}.modal-backdrop{position:fixed;inset:0;z-index:100;display:grid;place-items:center;background:rgba(0,0,0,.66);backdrop-filter:blur(5px);padding:4vh 4vw}.modal{width:min(80vw,1220px);height:min(80vh,860px);overflow:auto;padding:18px}.capture-modal{height:auto}.modal-head{display:flex;justify-content:space-between;gap:16px;align-items:flex-start;border-bottom:1px solid rgba(104,231,255,.12);padding-bottom:10px}.modal-head p{margin:0 0 5px;color:#68e7ff;text-transform:uppercase;letter-spacing:.18em;font-size:11px}.close{width:40px;height:40px;border-radius:50%;border:1px solid rgba(104,231,255,.2);background:rgba(255,255,255,.04);color:#dff8ff;font-size:26px;cursor:pointer}.modal-grid{display:grid;grid-template-columns:minmax(0,1fr) 340px;gap:18px;margin-top:14px}.editform{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}.editform label{display:grid;gap:5px;color:#8aa6b8;font-size:12px}.editform label:has(textarea),.proposal{grid-column:1/-1}.proposal{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:8px;padding:10px;border-radius:12px;background:rgba(104,231,255,.05)}.mini,.ref{display:block;width:100%;box-sizing:border-box;margin:5px 0;padding:8px;border-radius:9px;border:1px solid rgba(104,231,255,.14);background:rgba(255,255,255,.03);color:#dff8ff;text-align:left;cursor:pointer}.back{border-color:#ffd447;color:#ffd447}.muted,.card small,header span{color:#8aa6b8}@keyframes pop{0%{transform:scale(1)}35%{transform:scale(1.025);box-shadow:0 0 18px rgba(104,231,255,.42)}100%{transform:scale(1)}}@media(max-width:1100px){.work,.modal-grid,.editform{grid-template-columns:1fr}.authority{flex-wrap:wrap}.authority code{margin-left:0}.topbar{align-items:flex-start;flex-wrap:wrap}.modal{width:92vw;height:86vh}}
</style>
